placeholders = ", ".join("?" * len(customer_ids))
cursor.execute(
    f"SELECT * FROM olist_customers_dataset WHERE customer_id IN ({placeholders})",
    list(customer_ids),
)
key = [d[0] for d in cursor.description].index('customer_id')
rows_by_customer_id = {r[key]: r for r in cursor.fetchall()}
for customer_id in customer_ids:
    row = rows_by_customer_id.get(customer_id)
    if row:
        customers.append({"customer_id": row[0], "customer_city": row[3]})
